import { useState } from 'react';
import {
  JxCard,
  JxSteps,
  JxStepsItem,
  JxForm,
  JxFormField,
  JxInput,
  JxButton,
  JxButtonGroup,
  JxDivider,
  JxText,
  JxHeading,
  JxStack,
} from '@jinx-ui/react';

interface RegistrationData {
  fullName: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
}

interface RegistrationFormProps {
  onSubmit: (data: RegistrationData) => void;
}

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const INITIAL_DATA: RegistrationData = {
  fullName: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [currentStep, setCurrentStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(INITIAL_DATA);

  const updateField = (field: keyof RegistrationData) => (value: string) => {
    setData((prev) => ({ ...prev, [field]: value }));
  };

  const isLastStep = currentStep === STEPS.length - 1;
  const isFirstStep = currentStep === 0;

  const handleNext = () => {
    if (!isLastStep) {
      setCurrentStep((step) => step + 1);
    }
  };

  const handleBack = () => {
    if (!isFirstStep) {
      setCurrentStep((step) => step - 1);
    }
  };

  const handleSubmit = () => {
    onSubmit(data);
  };

  return (
    <JxCard className="jx-p-lg" style={{ maxWidth: 'var(--jx-size-md)' }}>
      <JxStack gap="lg">
        <JxSteps activeIndex={currentStep}>
          {STEPS.map((label, index) => (
            <JxStepsItem
              key={label}
              index={index}
              label={label}
              status={
                index < currentStep
                  ? 'completed'
                  : index === currentStep
                  ? 'active'
                  : 'pending'
              }
            />
          ))}
        </JxSteps>

        <JxDivider />

        {currentStep === 0 && (
          <JxForm>
            <JxHeading level={3}>Контакты</JxHeading>
            <JxFormField label="Полное имя" htmlFor="fullName">
              <JxInput
                id="fullName"
                value={data.fullName}
                onChange={updateField('fullName')}
                placeholder="Иван Иванов"
              />
            </JxFormField>
            <JxFormField label="Email" htmlFor="email">
              <JxInput
                id="email"
                type="email"
                value={data.email}
                onChange={updateField('email')}
                placeholder="ivan@example.com"
              />
            </JxFormField>
            <JxFormField label="Телефон" htmlFor="phone">
              <JxInput
                id="phone"
                type="tel"
                value={data.phone}
                onChange={updateField('phone')}
                placeholder="+7 900 000 00 00"
              />
            </JxFormField>
          </JxForm>
        )}

        {currentStep === 1 && (
          <JxForm>
            <JxHeading level={3}>Адрес</JxHeading>
            <JxFormField label="Страна" htmlFor="country">
              <JxInput
                id="country"
                value={data.country}
                onChange={updateField('country')}
                placeholder="Россия"
              />
            </JxFormField>
            <JxFormField label="Город" htmlFor="city">
              <JxInput
                id="city"
                value={data.city}
                onChange={updateField('city')}
                placeholder="Москва"
              />
            </JxFormField>
            <JxFormField label="Улица и дом" htmlFor="street">
              <JxInput
                id="street"
                value={data.street}
                onChange={updateField('street')}
                placeholder="ул. Ленина, 1"
              />
            </JxFormField>
            <JxFormField label="Почтовый индекс" htmlFor="zip">
              <JxInput
                id="zip"
                value={data.zip}
                onChange={updateField('zip')}
                placeholder="123456"
              />
            </JxFormField>
          </JxForm>
        )}

        {currentStep === 2 && (
          <JxStack gap="md">
            <JxHeading level={3}>Проверка данных</JxHeading>
            <JxText color="secondary">Пожалуйста, проверьте введённые данные перед отправкой.</JxText>

            <JxStack gap="xs">
              <JxText weight="bold">Контакты</JxText>
              <JxText>Имя: {data.fullName || '—'}</JxText>
              <JxText>Email: {data.email || '—'}</JxText>
              <JxText>Телефон: {data.phone || '—'}</JxText>
            </JxStack>

            <JxDivider />

            <JxStack gap="xs">
              <JxText weight="bold">Адрес</JxText>
              <JxText>Страна: {data.country || '—'}</JxText>
              <JxText>Город: {data.city || '—'}</JxText>
              <JxText>Улица: {data.street || '—'}</JxText>
              <JxText>Индекс: {data.zip || '—'}</JxText>
            </JxStack>
          </JxStack>
        )}

        <JxDivider />

        <JxButtonGroup justify="between">
          <JxButton variant="secondary" onClick={handleBack} disabled={isFirstStep}>
            Назад
          </JxButton>
          {isLastStep ? (
            <JxButton variant="primary" onClick={handleSubmit}>
              Отправить
            </JxButton>
          ) : (
            <JxButton variant="primary" onClick={handleNext}>
              Дальше
            </JxButton>
          )}
        </JxButtonGroup>
      </JxStack>
    </JxCard>
  );
}

